script:
html { scroll-behavior: smooth; }
::selection { background: #3D6B4A; color: #F7F7F3; }
.an-photo img { transition: transform 0.4s ease-out; }
.an-photo:hover img { transform: scale(1.02); }
.an-yr { transition: background-color 0.15s ease-out; }
.an-yr:hover { background-color: rgba(61, 107, 74, 0.08); }
.an-yr .an-yr-arrow { transition: transform 0.15s ease-out; }
.an-yr:hover .an-yr-arrow { transform: translateX(4px); color: #3D6B4A; }
@keyframes an-pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.35; } }
.an-pulse { animation: an-pulse 2.4s ease-in-out infinite; }
html[data-theme="dark"] .an-nav { background-color: rgba(18, 20, 15, 0.8) !important; }
